WITH with_last AS (SELECT s.id, s.browser, s.started_at, s.country, latest.web_event_event_time, latest.web_event_page FROM sessions s LEFT JOIN LATERAL (SELECT c.event_time AS web_event_event_time, c.page AS web_event_page FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT DATE_TRUNC('YEAR', started_at) AS year_start, browser, MIN(web_event_event_time) AS first_seen, COUNT_IF(web_event_page = '/cart') AS cart_events, COUNT(*) FILTER (WHERE browser = 'Edge') AS edge_rows, COUNT(DISTINCT web_event_page) AS distinct_web_event_pages, COUNT(CASE WHEN country = 'DE' THEN 1 END) AS de_count, SORT_ARRAY(COLLECT_SET(web_event_page)) AS web_event_page_list, GROUPING(DATE_TRUNC('YEAR', started_at)) AS gid FROM with_last GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', started_at), browser), (DATE_TRUNC('YEAR', started_at)), ()) ORDER BY year_start NULLS LAST;
